  const errors = captureErrors();

  it('answers list_sessions with ISO session_list frames, empty when listFor is absent, and SERVER_ERROR with a ws log on failure', async () => {
    const seen: Array<{userId: string | number; options?: SessionListOptions}> = [];
    const createdAt = new Date('2026-01-01T00:00:00.000Z');
    const updatedAt = new Date('2026-01-01T00:02:00.000Z');
    const summary: SessionSummary = {sessionId: 's2', createdAt, updatedAt, entryCount: 4};
    const before: SessionCursor = {updatedAt: '2026-01-01T00:05:00.000Z', sessionId: 's3'};

    const sendWithStore = async (sessionStore?: SessionStore) => {
      const sent: OutgoingMessage[] = [];
      const ws = {send: (raw: string) => sent.push(JSON.parse(raw) as OutgoingMessage)} as unknown as WebSocket;
      const orchestrator = {processMessageStream: jest.fn()} as unknown as ChatOrchestrator;
      const session: ChatSession = {sessionId: 's1', userId: 'u1', entries: []};
